// The two stable-interface negotiation transactions the generated
// server answers.  They are not in the method table above.
pub fn dispatch_interface_query(code: u32, out_p: &mut Parcel) -> Option<i32> {
    match code {
        TXN_GET_INTERFACE_VERSION => {
            if !out_p.write_status_ok() {
                return Some(STATUS_UNKNOWN_TRANSACTION);
            }
            out_p.write_i32(INTERFACE_VERSION);
            Some(STATUS_OK)
        }
        TXN_GET_INTERFACE_HASH => {
            if !out_p.write_status_ok() {
                return Some(STATUS_UNKNOWN_TRANSACTION);
            }
            out_p.write_string(INTERFACE_HASH);
            Some(STATUS_OK)
        }
        _ => None,
    }
}

/// The structured-parcelable write: a 4-byte size placeholder, the
/// fields, then the size backpatched.  Identical to the generated
/// testKitFeatureTestResult::writeToParcel.
fn write_parcelable(out_p: &mut Parcel, r: &TestKitResult) {
    // The generated Bp reads the return with ndk::AParcel_readParcelable,
    // which consumes a non-null marker int32 before the parcelable body
    // (binder_parcel_utils.h: AParcel_writeParcelable writes 1 first).
    // Omitting it makes the client read the size field as the marker and
    // then fail with STATUS_BAD_VALUE on the size check.
    out_p.write_i32(1);
    let start = out_p.data_position();
    out_p.write_i32(0);
    out_p.write_i32(r.ret);
    out_p.write_string(&r.str);
    let end = out_p.data_position();
    out_p.set_data_position(start);
    out_p.write_i32(end - start);
    out_p.set_data_position(end);
}
